<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
$user=require_login(['office_head','supervisor']);$officeId=(int)$user['office_id'];$dateFrom=trim((string)($_GET['date_from']??''));$dateTo=trim((string)($_GET['date_to']??''));$includeVoid=isset($_GET['include_void'])&&$user['role']==='office_head';$where=['f.office_id=?'];$params=[$officeId];if($dateFrom!==''){$where[]='f.visit_date>=?';$params[]=$dateFrom;}if($dateTo!==''){$where[]='f.visit_date<=?';$params[]=$dateTo;}if(!$includeVoid)$where[]='f.is_void=0';$stmt=db()->prepare("SELECT f.* FROM feedback f WHERE ".implode(' AND ',$where)." ORDER BY f.visit_date DESC,f.id DESC");$stmt->execute($params);$rows=$stmt->fetchAll();
if(($_GET['export']??'')==='csv'){$export=[];foreach($rows as $r)$export[]=[$r['id'],$r['visit_date'],$r['sex'],$r['age'],$r['client_type'],$r['service_received'],$r['timeliness_rating'],$r['client_handling_rating'],$r['quality_rating'],$r['overall_rating'],$r['average_rating'],$r['comment'],$r['sentiment'],$r['sentiment_confidence'],$r['sentiment_source'],$r['review_status'],$r['final_score'],$r['source'],$r['submitted_at']];audit((int)$user['id'],'report_csv_export',$user['office_code'].' exported '.count($rows).' rows');csv_download(strtolower($user['office_code']).'-feedback-'.date('Y-m-d').'.csv',['ID','Visit Date','Sex','Age','Client Type','Service','Timeliness','Client Handling','Quality','Overall','Average Rating','Comment','Sentiment','Confidence','Classifier Source','Review Status','Final Score','Record Source','Submitted At'],$export);}
$m=dashboard_metrics($officeId,$dateFrom?:null,$dateTo?:null,true,$includeVoid);$ages=age_group_counts($officeId,$dateFrom?:null,$dateTo?:null,true,$includeVoid);$services=service_summary($officeId,10,$dateFrom?:null,$dateTo?:null,true,$includeVoid);$ratingDistribution=rating_distribution($officeId,$dateFrom?:null,$dateTo?:null);$clientRows=client_output_rows($officeId,$dateFrom?:null,$dateTo?:null);$clientTotal=array_sum(array_column($clientRows,'client_count'));$clientDays=count($clientRows);$clientPeak=$clientRows?max(array_column($clientRows,'client_count')):0;$clientAverage=$clientDays?$clientTotal/$clientDays:0;$goodInsights=[];$criticalInsights=[];foreach($rows as $insightRow){if($insightRow['sentiment']==='positive'&&count($goodInsights)<5)$goodInsights[]=$insightRow;if($insightRow['sentiment']==='negative'&&count($criticalInsights)<5)$criticalInsights[]=$insightRow;if(count($goodInsights)>=5&&count($criticalInsights)>=5)break;}render_dashboard_start('Office Reports','reports');page_header($user['office_code'].' Reports & Export','Every summary and detailed row follows the selected date range.','<button type="button" class="btn secondary" data-modal-open="office-export-modal">Export Report</button>');
?>
