<form class="filters wide" method="get"><label class="filter-field"><span>From</span><input type="date" name="date_from" value="<?= e($dateFrom) ?>"></label><label class="filter-field"><span>To</span><input type="date" name="date_to" value="<?= e($dateTo) ?>"></label><?php if($user['role']==='office_head'): ?><label class="checkbox-inline"><input type="checkbox" name="include_void" value="1" <?= $includeVoid?'checked':'' ?>> Include void</label><?php endif; ?><button class="btn">Generate</button></form>
<div class="stats-grid" data-report-section="summary"><div class="stat-card"><small>Responses</small><strong><?= count($rows) ?></strong></div><div class="stat-card"><small>Average Rating</small><strong><?= number_format($m['avg_rating'],2) ?>/4</strong></div><div class="stat-card"><small>Final Score</small><strong><?= number_format($m['avg_final'],2) ?>%</strong></div><div class="stat-card"><small>Positive Rate</small><strong><?= number_format($m['positive_rate'],1) ?>%</strong></div><div class="stat-card"><small>Action Completion</small><strong><?= number_format($m['completion_rate'],1) ?>%</strong></div><div class="stat-card"><small>Avg. Open Action</small><strong><?= number_format($m['avg_open_hours']/24,1) ?> days</strong></div><div class="stat-card"><small>Avg. Resolution</small><strong><?= number_format($m['avg_resolution_hours']/24,1) ?> days</strong></div></div>
<div class="content-grid"><section class="card" data-report-section="ages"><div class="card-head"><div><h2>Age Groups</h2></div></div><div class="chart-box"><canvas data-chart='<?= e(json_encode(array_map(fn($r)=>['label'=>$r['label'],'value'=>(int)$r['count']],$ages))) ?>' data-type="bar"></canvas></div></section><section class="card" data-report-section="services"><div class="card-head"><div><h2>Service Performance</h2></div></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Responses</th><th>Score</th><th>Negative</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><?= e($s['label']) ?></td><td><?= (int)$s['responses'] ?></td><td><?= number_format((float)$s['avg_score'],2) ?>%</td><td><?= (int)$s['negative_count'] ?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<section class="card" data-report-section="details"><div class="card-head"><div><h2><?= e($user['office_name']) ?> Feedback Report</h2><p><?= count($rows) ?> record(s)</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Service</th><th>Client</th><th>Rating</th><th>Sentiment</th><th>Final</th><th>Comment</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="<?= $r['is_void']?'void-row':'' ?>"><td><?= e($r['visit_date']) ?></td><td><?= e($r['service_received']) ?></td><td><?= e($r['client_type']) ?><br><span class="muted"><?= (int)$r['age'] ?> · <?= e($r['sex']) ?></span></td><td><?= number_format((float)$r['average_rating'],2) ?>/4</td><td><?= badge(status_label($r['sentiment']),$r['sentiment']) ?><br><span class="muted"><?= e($r['review_status']) ?></span></td><td><?= number_format((float)$r['final_score'],2) ?>%</td><td><?= e($r['comment']) ?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty-state">No records in this date range.</td></tr><?php endif;?></tbody></table></div></section>
<div class="content-grid" data-report-section="insights"><section class="card"><div class="card-head"><div><h2>Positive Feedback Insights</h2><p>Five most recent positive comments.</p></div></div><div class="notification-list"><?php foreach($goodInsights as $item):?><article class="notification-item"><div class="notification-dot"></div><div><strong><?= e(date('M d, Y',strtotime($item['visit_date']))) ?></strong><p><?= e($item['comment']) ?></p></div></article><?php endforeach;?><?php if(!$goodInsights):?><div class="empty-state">No positive feedback in this range.</div><?php endif;?></div></section><section class="card"><div class="card-head"><div><h2>Critical Feedback Insights</h2><p>Five most recent negative comments.</p></div></div><div class="notification-list"><?php foreach($criticalInsights as $item):?><article class="notification-item unread"><div class="notification-dot"></div><div><strong><?= e(date('M d, Y',strtotime($item['visit_date']))) ?></strong><p><?= e($item['comment']) ?></p></div></article><?php endforeach;?><?php if(!$criticalInsights):?><div class="empty-state">No critical feedback in this range.</div><?php endif;?></div></section></div>
<section class="card" data-report-section="clients"><div class="card-head"><div><h2>Client Count</h2><p>Catered-client output within the selected date range.</p></div></div><div class="stats-grid mini"><div class="stat-card"><small>Total Clients</small><strong><?= (int)$clientTotal ?></strong></div><div class="stat-card"><small>Daily Average</small><strong><?= number_format($clientAverage,1) ?></strong></div><div class="stat-card"><small>Peak Day</small><strong><?= (int)$clientPeak ?></strong></div><div class="stat-card"><small>Active Days</small><strong><?= $clientDays ?></strong></div></div></section>
<section class="card" data-report-section="ratings"><div class="card-head"><div><h2>Rating Distribution</h2><p>Actual response counts for every rating criterion.</p></div></div><div class="table-wrap"><table><thead><tr><th>Criterion</th><th>4 — Strongly Agree</th><th>3 — Agree</th><th>2 — Disagree</th><th>1 — Strongly Disagree</th><th>Total</th></tr></thead><tbody><?php foreach($ratingDistribution as $item):?><tr><td><strong><?= e($item['label']) ?></strong></td><td><?= (int)$item['4'] ?></td><td><?= (int)$item['3'] ?></td><td><?= (int)$item['2'] ?></td><td><?= (int)$item['1'] ?></td><td><strong><?= (int)$item['total'] ?></strong></td></tr><?php endforeach;?></tbody></table></div></section>
